def transform(grid):
    h, w = len(grid), len(grid[0])

    row_seps = [r for r in range(h) if all(v == 3 for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]

    def intervals(length, seps):
        result = []
        start = 0
        for s in seps:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < length:
            result.append((start, length))
        return result

    rows = intervals(h, row_seps)
    cols = intervals(w, col_seps)
    regions = [(r0, r1, c0, c1)
               for r0, r1 in rows for c0, c1 in cols]

    source = max(
        regions,
        key=lambda box: sum(
            grid[r][c] != 7
            for r in range(box[0], box[1])
            for c in range(box[2], box[3])
        )
    )
    r0, r1, c0, c1 = source
    motif = [
        (r - r0, c - c0, grid[r][c])
        for r in range(r0, r1)
        for c in range(c0, c1)
        if grid[r][c] != 7
    ]

    out = [row[:] for row in grid]
    for a, b, x, y in regions:
        if (b - a, y - x) != (r1 - r0, c1 - c0):
            continue
        for dr, dc, color in motif:
            out[a + dr][x + dc] = color

    return out
